import sys
import os


class DataReader:
    def __init__(self, reader):
        self.reader = reader
        self.st = None

    @staticmethod
    def create_from_file(name):
        return DataReader(open(name, "r"))

    def next(self):
        while self.st is None or len(self.st) == 0:
            s = self.reader.readline()
            if not s:
                return None
            self.st = s.split()
        return self.st.pop(0)

    def next_token(self):
        return self.next()

    def next_int(self):
        return int(self.next_token())

    def next_long(self):
        return int(self.next_token())

    def read_int_array(self, n):
        return [self.next_int() for _ in range(n)]

    def next_line(self):
        return self.reader.readline()

    def solve(self, out):
        n = self.next_int()
        k = self.next_int()

        s = self.next_token()

        used = [False] * n

        def dfs(u):
            if u < 0 or u >= n or used[u] or s[u] == '#':
                return False
            if s[u] == 'T':
                return True
            used[u] = True

            return dfs(u - k) or dfs(u + k)

        out.write(to_yes_no(dfs(s.index('G'))) + "\n")


def to_yes_no(value):
    return "YES" if value else "NO"


def main():
    sys.setrecursionlimit(1000000)
    if os.environ.get("ONLINE_JUDGE") is None:
        r = open("input.txt", "r")
        out = open("output.txt", "w")
    else:
        r = sys.stdin
        out = sys.stdout

    DataReader(r).solve(out)
    out.flush()


main()
